#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/evp.h>
#include <openssl/hmac.h>
#include <openssl/rand.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <errno.h>

#define MAX_HEADER_SIZE 8192
#define MAX_BODY_SIZE 65536
#define MAX_ROLES 16
#define ROLE_NAME_MAX 64
#define TOKEN_SIZE 32
#define HMAC_SIZE 32

typedef struct {
    char username[128];
    uint32_t user_id;
    uint8_t role_count;
    char roles[MAX_ROLES][ROLE_NAME_MAX];
    time_t issued_at;
    time_t expires_at;
    uint8_t hmac[HMAC_SIZE];
} auth_token_t;

static uint8_t g_signing_key[32];
static int g_initialized = 0;

int init_auth_system(void) {
    if (RAND_bytes(g_signing_key, sizeof(g_signing_key)) != 1)
        return -1;
    g_initialized = 1;
    return 0;
}

static int constant_time_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    volatile uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0 ? 0 : -1;
}

static int compute_token_hmac(const auth_token_t *token, uint8_t *out_hmac) {
    unsigned int hmac_len = 0;
    /* HMAC over all fields except the hmac field itself */
    size_t data_len = offsetof(auth_token_t, hmac);
    uint8_t *result = HMAC(EVP_sha256(), g_signing_key, sizeof(g_signing_key),
                           (const uint8_t *)token, data_len,
                           out_hmac, &hmac_len);
    if (!result || hmac_len != HMAC_SIZE)
        return -1;
    return 0;
}

static int verify_token_hmac(const auth_token_t *token) {
    uint8_t expected_hmac[HMAC_SIZE];
    if (compute_token_hmac(token, expected_hmac) != 0)
        return -1;
    return constant_time_compare(expected_hmac, token->hmac, HMAC_SIZE);
}

int create_auth_token(const char *username, uint32_t user_id,
                      const char **roles, int role_count,
                      auth_token_t *token_out) {
    if (!g_initialized) return -1;
    if (!username || strlen(username) >= sizeof(token_out->username))
        return -1;
    if (role_count < 0 || role_count > MAX_ROLES)
        return -1;

    memset(token_out, 0, sizeof(auth_token_t));
    strncpy(token_out->username, username, sizeof(token_out->username) - 1);
    token_out->user_id = user_id;
    token_out->role_count = (uint8_t)role_count;
    token_out->issued_at = time(NULL);
    token_out->expires_at = token_out->issued_at + 3600; /* 1 hour */

    for (int i = 0; i < role_count; i++) {
        if (!roles[i] || strlen(roles[i]) >= ROLE_NAME_MAX)
            return -1;
        strncpy(token_out->roles[i], roles[i], ROLE_NAME_MAX - 1);
    }

    return compute_token_hmac(token_out, token_out->hmac);
}

/* Check if token holder has a specific role */
static int token_has_role(const auth_token_t *token, const char *required_role) {
    /* role_count is uint8_t, iterate checking bounds */
    if (token->role_count > MAX_ROLES)
        return 0;
    for (uint8_t i = 0; i < token->role_count; i++) {
        if (strncmp(token->roles[i], required_role, ROLE_NAME_MAX) == 0)
            return 1;
    }
    return 0;
}

typedef struct {
    const char *path;
    const char *method;
    const char *required_role;
    int min_clearance;
} route_acl_t;

static const route_acl_t g_acl_table[] = {
    {"/api/admin/users", "GET", "admin", 5},
    {"/api/admin/config", "POST", "admin", 8},
    {"/api/data/export", "GET", "analyst", 3},
    {"/api/data/import", "POST", "analyst", 3},
    {"/api/user/profile", "GET", "user", 1},
    {NULL, NULL, NULL, 0}
};

typedef struct {
    char method[16];
    char path[256];
    char token_b64[1024];
    char body[MAX_BODY_SIZE];
    size_t body_len;
    int clearance_level;
} http_request_t;

static int parse_clearance_header(const char *header_value) {
    /* Parse X-Clearance-Level header, returns clearance as int */
    if (!header_value) return 0;
    long val = strtol(header_value, NULL, 10);
    if (val < 0 || val > 10) return 0;
    return (int)val;
}

/* Authorization check: verify token is valid and has required permissions */
int authorize_request(const http_request_t *req, const auth_token_t *token) {
    /* Step 1: Verify HMAC integrity */
    if (verify_token_hmac(token) != 0) {
        return -1; /* tampered token */
    }

    /* Step 2: Check expiration */
    time_t now = time(NULL);
    if (now > token->expires_at || now < token->issued_at) {
        return -2; /* expired or future token */
    }

    /* Step 3: Find matching ACL entry */
    const route_acl_t *acl = NULL;
    for (int i = 0; g_acl_table[i].path != NULL; i++) {
        if (strncmp(req->path, g_acl_table[i].path, 256) == 0 &&
            strncmp(req->method, g_acl_table[i].method, 16) == 0) {
            acl = &g_acl_table[i];
            break;
        }
    }

    if (!acl) {
        return -3; /* no matching route */
    }

    /* Step 4: Check role */
    if (!token_has_role(token, acl->required_role)) {
        return -4; /* insufficient role */
    }

    /* Step 5: Check clearance level */
    if (req->clearance_level < acl->min_clearance) {
        return -5; /* insufficient clearance */
    }

    return 0; /* authorized */
}

/* Decode token from base64 in request */
static int decode_token_from_request(const http_request_t *req, auth_token_t *token) {
    size_t b64_len = strlen(req->token_b64);
    if (b64_len == 0 || b64_len > 4096)
        return -1;

    /* Base64 length must be a multiple of 4 for a well-formed encoding */
    if ((b64_len % 4) != 0)
        return -1;

    /*
     * Fix (CWE-120): EVP_DecodeBlock writes (b64_len/4)*3 bytes, which may
     * exceed sizeof(auth_token_t). Decode into a large-enough temporary
     * buffer, then validate the exact decoded length before copying into
     * the fixed-size token structure.
     */
    size_t max_decoded = (b64_len / 4) * 3;
    uint8_t *tmp = (uint8_t *)malloc(max_decoded);
    if (!tmp)
        return -1;

    int decoded_len = EVP_DecodeBlock(tmp,
                                      (const uint8_t *)req->token_b64,
                                      (int)b64_len);
    if (decoded_len < 0) {
        free(tmp);
        return -1;
    }

    /* Account for base64 padding: EVP_DecodeBlock does not subtract padding */
    size_t actual_len = (size_t)decoded_len;
    if (b64_len >= 1 && req->token_b64[b64_len - 1] == '=') actual_len--;
    if (b64_len >= 2 && req->token_b64[b64_len - 2] == '=') actual_len--;

    if (actual_len != sizeof(auth_token_t)) {
        free(tmp);
        return -1;
    }

    memcpy(token, tmp, sizeof(auth_token_t));
    free(tmp);
    return 0;
}

/* Main request handler */
int handle_request(const http_request_t *req) {
    if (!g_initialized) return -1;

    auth_token_t token;
    memset(&token, 0, sizeof(token));

    if (decode_token_from_request(req, &token) != 0) {
        return -1; /* invalid token encoding */
    }

    int auth_result = authorize_request(req, &token);
    if (auth_result != 0) {
        return auth_result;
    }

    /* Request authorized - process it */
    return 0;
}
